  /** CARD path only: the hold `payAndDeployGame` reserved before the card was
   *  charged (see reserveOrderCoupon), confirmed here — RESERVED→CONSUMED —
   *  inside the same tx that commits the order. Mirrors lib/order.ts
   *  placeOrder's `opts.couponReservationToken` exactly. */
  couponReservationToken?: string | null,
): Promise<string> {
  const quote = await gameOrderQuote(intent, { userId: user.id });

  // Resolve the ACTUAL hostname this server will get, now that the order is
  // really being placed (NOT inside gameOrderQuote, which the wizard calls on
  // every keystroke for a live price preview and has no business hitting the
  // DB or handing out a name it might never use). gameOrderQuote already
  // validated the format (or generated the "<family>-<rand>" default); this
  // only resolves UNIQUENESS, auto-suffixing on collision instead of letting
  // two customers' servers end up with the same hostname. See lib/hostname.ts.
  quote.hostname = await resolveUniqueHostname(quote.hostname, quote.gameFamily);

  // CS2 needs a Steam Game Server Login Token to register with matchmaking at
  // all (SRCDS_TOKEN, no longer a required checkout field as of 2026-09-17 —
  // see lib/game-config.ts's field comment). Mint one automatically, ONCE,
  // here at actual order placement — never in gameOrderQuote, which the
  // wizard calls on every keystroke for a live price preview and would burn
  // through Valve's 1000-account-per-key budget on customers who never buy.
  // A customer who pasted their own token is left alone; a Steam API hiccup
  // degrades to "no token yet" (server still deploys and runs, just isn't
  // listed on matchmaking until one is added from the dashboard) rather than
  // failing the whole paid order over it.
  if (quote.gameFamily === "cs2" && !quote.values.SRCDS_TOKEN && steamGsltConfigured()) {
    try {
      const account = await createGameServerAccount(730, `nxeon:${quote.hostname}`);
      quote.values.SRCDS_TOKEN = account.loginToken;
      quote.values._SRCDS_TOKEN_STEAMID = account.steamid;
    } catch (e) {
      console.error(`[game-order] Steam GSLT auto-generation failed for ${quote.hostname}`, e);
    }
  }

  // Bill off the SOLD price when present (never re-priced after the card cleared),
  // else the fresh quote (which already folds in any valid coupon discount) —
  // this scalar is the whole truth about what this order costs.
  const chargeCents = sold?.chargeCents ?? quote.chargeCents;

  // Oversell guard — the VPS order path enforces this; game orders must too, or a
  // game server could commit host RAM past capacity.
  const capacity = await capacityCheck(quote.basePlanId);
  if (!capacity.ok) {
    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
  }

  // Pick a node the same way a VPS order does — without this, every game
  // server's `nodeId` stays null and `worker/index.ts`'s `nodeFor()` fallback
  // (`server.node ?? primary node`) pins EVERY game server onto the primary
  // node forever, regardless of its actual load. Confirmed live: every game
  // server in production had nodeId: null and primary sat at 84% real RAM /
  // 200% committed CPU while other nodes were comparatively idle.
  //
  // Region-aware exactly like lib/order.ts placeOrder: a customer picks a
  // REGION, not a specific node, so it is resolved fresh here (least loaded
  // within that region) rather than trusting whatever node the wizard's
  // local preview happened to resolve at page-load time.
  // Only nodes that actually have this image's base template (lib/node-templates.ts).
  const tplRow = await db.osTemplate.findUnique({ where: { id: quote.osTemplateId }, select: { vmid: true, baseVmid: true } });
  const templateVmid = tplRow ? tplRow.baseVmid ?? tplRow.vmid : null;
  const node = intent.region
    ? await scheduleNode(quote.ramMB, { region: intent.region, provider: intent.provider, templateVmid })
    : await scheduleNode(quote.ramMB, { templateVmid });
  if (intent.region && !node) {
    throw new GameOrderError("That location is at capacity right now — please pick another.");
  }
  // Same for the no-region path: null with real nodes configured means every
  // node refused (template missing or the live RAM guard). Without this the
  // order would go through with nodeId null and the worker would put the VM
  // on the primary regardless of its RAM (lib/node-ram-guard.ts).
  if (!node && (await db.node.count({ where: { enabled: true } })) > 0) {
    throw new GameOrderError("We're at capacity right now — please try again shortly or contact support.");
  }

  // WALLET path: claim the coupon atomically BEFORE the balance gate/order tx,
  // so a wallet order fails cleanly (no money moved) if the code's last slot just
  // went, or this person already used it. Mirrors lib/order.ts placeOrder's own
  // wallet-path claim exactly (same shared claimOrderCoupon — one redemption
  // ledger for both VPS and game orders, not two).
  //
  // CARD path: does NOT claim here — `sold` means the card already charged the
  // discounted price, so a fresh claim now would double-count against the cap.
  // Real per-person enforcement for the card leg happens BEFORE the charge, via
  // `payAndDeployGame`'s reserveOrderCoupon hold (mirroring VPS's cardPromoToken);
  // this function only CONFIRMS that pre-existing hold below, inside the same tx
  // that commits the order — see confirmOrderCouponReservation's call site further
  // down. Added 2026-09-23 after a real gap: this path used to not gate the card
  // leg on any per-person limit at all, which the trial promo (a strictly
  // one-per-person, excludeActiveCustomers coupon) needed and didn't have.
  if (!sold && quote.couponId && quote.couponDiscountCents > 0) {
    try {
      await claimOrderCoupon({
        couponId: quote.couponId,
        maxRedemptions: quote.couponMaxRedemptions,
        firstTimeOnly: quote.couponFirstTimeOnly,
        excludeActiveCustomers: quote.couponExcludeActiveCustomers,
        userId: user.id,
        ipHash: null,
        amountCents: quote.couponDiscountCents,
      });
    } catch (e) {
      // claimOrderCoupon throws OrderError — translate to GameOrderError so
      // callers that only catch GameOrderError (payAndDeployGame, orderGameServer)
      // still surface this as a friendly inline message instead of an uncaught
      // exception / generic error page.
      throw new GameOrderError(e instanceof Error ? e.message : "That code couldn't be applied.");
    }
  }

