 * either one at all: it creates its `Server` row with no `nodeId`, so every
 * game server ever ordered falls through `worker/index.ts`'s `nodeFor()`
 * fallback (`server.node ?? primary node`) and lands on the PRIMARY node
 * regardless of its actual load. Confirmed live: `primary` sits at 84% real
 * RAM and 200% committed CPU while other nodes are comparatively idle, and
 * every game server in production has `nodeId: null`. Fixed by giving
 * `game-order.ts` the same real scheduler VPS/NxCloud orders already use,
 * rather than writing a fourth copy or leaving it unscheduled.
 *
 * Returns null when no node qualifies — including (since 2026-10-01) when
 * the live RAM guard refuses every candidate. Callers must treat null as
 * "no capacity", never as "let the worker fall back to the primary".
 */
export async function scheduleNode(
  planRamMB: number,
  // templateVmid: the Proxmox template this order clones (OsTemplate.baseVmid
  // ?? vmid). When given, nodes that do not have it are never chosen — see
  // lib/node-templates.ts for the incident. Omitted = previous behaviour.
  opts?: { provider?: NodeProvider; region?: string; templateVmid?: number | null },
) {
  // Customer picks a REGION (e.g. "Singapore"), never a specific physical
  // node — multiple nodes can share one region (primary + node-3 are both
  // OVH/sgp1), and forcing a customer's choice onto one specific node meant
  // that node alone ever took new signups for that region, regardless of its
  // actual load relative to its sibling in the same region. Filtering here
  // (rather than a separate function) keeps this the single place "which
  // node wins" is decided, with or without a region constraint.
  const nodes = await db.node.findMany({
    where: {
      enabled: true,
      status: "ONLINE",
      // Distinct from `enabled` — a node can stay visible/online with its
      // existing servers running and still be excluded from taking NEW ones
      // (the admin Infrastructure page's per-node toggle).
      acceptsProvisions: true,
      ...(opts?.region ? { region: opts.region } : {}),
      ...(opts?.provider ? { provider: opts.provider } : {}),
    },
  });
  if (nodes.length === 0) return null;
  let candidates = nodes;
  if (opts?.templateVmid && !SANDBOX) {
    const tv = opts.templateVmid;
    const lookup = new Map(await Promise.all(nodes.map(async (n) => [n.id, await nodeTemplateVmids(n)] as const)));
    const { ok, missing } = nodesWithTemplate(nodes, tv, lookup);
    if (missing.length > 0) {
      logError("node-scheduler", new Error(`template ${tv} missing on ${missing.map((m) => m.name).join(", ")}`), {
        templateVmid: tv,
        excluded: missing.map((m) => m.name),
        note: "these nodes were skipped for this order; copy the template to them (scripts/onboard-node.sh) to restore capacity",
      });
    }
    if (ok.length === 0) return null;
    candidates = ok;
  }
  const loads = await Promise.all(
    candidates.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
      });
      // A game server's real commitment is its game plan's ram, not the
      // (larger) base VPS plan it rides on — overstating every game server's
      // load here skews which node the scheduler picks for the NEXT one.
      const used = agg.reduce((s, r) => s + (r.gamePlan?.ramMB ?? r.plan.ramMB), 0);
      // Commitment AFTER this VM lands — that's what decides whether placing
      // here tips the node critical.
      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
      return { node: n, free: n.capacityRamMB - used, projectedPct };
    }),
  );
  // LIVE RAM GUARD (2026-10-01). Customer VMs are pinned to their plan RAM
  // (lib/vm-memory-policy.ts), so Proxmox can no longer balloon them down
  // when a node fills up. Before that, the "least-bad if every node is
  // critical" fallback below was softened by ballooning; with pinned RAM it
  // would be a real over-commit and the host OOM-killer picks a customer
  // VM. So every candidate must also pass the live guard (real configs of
  // every running VM incl. platform VMs, vs physical RAM minus the host
  // reserve) — see lib/node-ram-guard.ts. The DB-committed rule above is
  // unchanged and still applies (it covers stopped VMs the live view can't).
  // NXEON_RAM_GUARD=warn (default, log only) | enforce | off.
  let guarded = loads;
  const guardMode = ramGuardMode();
  if (guardMode !== "off" && !SANDBOX) {
    const verdicts = await Promise.all(loads.map((l) => nodeRamGuard(l.node, planRamMB)));
    const refused = loads
      .map((l, i) => ({ name: l.node.name, v: verdicts[i] }))
      .filter((x) => !x.v.ok);
    if (refused.length > 0) {
      logError("node-ram-guard", new Error(`RAM guard refused ${refused.map((r) => r.name).join(", ")} for a ${planRamMB} MB VM`), {
        mode: guardMode,
        refused: refused.map((r) => ({ node: r.name, reason: r.v.reason, unknown: r.v.unknown })),
      });
    }
    if (guardMode === "enforce") {
      guarded = loads.filter((_, i) => verdicts[i].ok);
      if (guarded.length === 0) return null;
    }
  }
  const { critPct } = await nodeThresholds();
  const roomy = guarded.filter((l) => l.projectedPct < critPct);
  const pool = roomy.length > 0 ? roomy : guarded;
  pool.sort((a, b) => b.free - a.free);
  return pool[0].node;
}

/**
 * True only when EVERY enabled compute node is at/above its RAM warn
 * threshold — the signal for the public "reserve your server now" banner.
 * A single loaded node must NOT trigger this: `scheduleNode()` can still
 * place a new order on a roomier node, so warning the public the moment
 * only one host is busy would be a false "we're out of capacity" claim.
 * Deliberately internals-free for the caller — no node names, no percentages,
 * no "Host"/"committed RAM" — this is a customer-facing scarcity signal, not
 * an ops metric (see lib/capacity.ts's ops-facing capacitySnapshot for that).
 */
export async function fleetNearCapacity(): Promise<boolean> {
  const t = await nodeThresholds();
  const nodes = (await proxmoxNodeUtil(t)).filter((n) => n.enabled);
  if (nodes.length === 0) return false;
  return nodes.every((n) => {
    const ram = n.dims.find((d) => d.dimension === "RAM");
    return (ram?.pct ?? 0) >= t.warnPct;
  });
}

