async function quoteGameOrderForExternalPayment(
  formData: FormData,
): Promise<{ error: string } | { cardCents: number; metadata: Record<string, string> }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const gateErr = await gameOrderGate(user);
  if (gateErr) return { error: gateErr };

  const intent = gameIntentFromFormData(formData);
  let quote;
  try {
    quote = await gameOrderQuote(intent, { userId: user.id });
  } catch (e) {
    if (e instanceof GameOrderError) return { error: e.message };
    throw e;
  }
  const chargeCents = quote.chargeCents;
  const useWallet = formData.get("useWallet") !== "0";
  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });
  if (cardCents <= 0) {
    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
  }

  // CLOSES A REAL GAP found 2026-09-22 building the trial-promo coupon: unlike
  // the VPS card/PayPal paths (both call reserveOrderCoupon before checkout),
  // a game order paid by card/PayPal/Coinbase previously enforced NO per-person
  // coupon guard at all — firstTimeOnly and now excludeActiveCustomers were
  // silently bypassable simply by not paying from the wallet. This was already
  // known and documented (see placeGameOrder's own comment on the wallet-only
  // claimOrderCoupon call) as "acceptable for a narrow, single-use flash-sale
  // code; revisit before ever running a coupon here that must be strictly
  // one-per-person on the card path too" — this promo is exactly that case.
  // orderCouponClaimable is a read-only, advisory check (no atomic hold, so a
  // true race could still slip through — same caveat the VPS path already
  // accepts), reused here for its first real caller.
  if (quote.couponId && quote.couponDiscountCents > 0) {
    const check = await orderCouponClaimable({
      couponId: quote.couponId,
      firstTimeOnly: quote.couponFirstTimeOnly,
      excludeActiveCustomers: quote.couponExcludeActiveCustomers,
      maxRedemptions: quote.couponMaxRedemptions,
      userId: user.id,
      ipHash: hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null,
    });
    if (!check.ok) return { error: check.error };
  }

  const sold: GameOrderPrice = {
    chargeCents,
    partnerDiscountCents: quote.partnerDiscountCents,
    partnerDiscountTier: quote.partnerDiscountTier,
  };
  const slim = {
    gamePlanId: intent.gamePlanId,
    termMonths: intent.termMonths,
    serverName: intent.serverName,
    hostname: intent.hostname,
    variant: intent.variant,
    subdomain: intent.subdomain,
    dedicatedIp: intent.dedicatedIp,
  };
  const configJson = intent.config ? JSON.stringify(intent.config) : "";
  const carryConfig = configJson !== "" && configJson.length <= 480;
  const metadata: Record<string, string> = {
    nxeonUserId: user.id,
    nxeonGameOrder: packExternalPaymentMetadata("Game order intent", slim),
    nxeonGameOrderPrice: packExternalPaymentMetadata("Game order price", sold),
    ...(carryConfig ? { nxeonGameConfig: configJson } : {}),
  };
  return { cardCents, metadata };
}

