 * the country was actually recognised (drives the "geo" vs "default" source).
 */
export function regionForCountry(country: string | null | undefined): { region: string; known: boolean } {
  const cc = (country ?? "").trim().toUpperCase();
  if (cc.length === 2) {
    if (SGP1_COUNTRIES.has(cc)) return { region: "sgp1", known: true };
    if (FSN1_COUNTRIES.has(cc)) return { region: "fsn1", known: true };
    if (BHS1_COUNTRIES.has(cc)) return { region: "bhs1", known: true };
  }
  return { region: DEFAULT_REGION, known: false };
}

/** Great-circle distance in km between two regions' datacentres. Unknown region -> Infinity. */
export function regionDistanceKm(a: string, b: string): number {
  const p = REGION_COORDS[a];
  const q = REGION_COORDS[b];
  if (!p || !q) return Infinity;
  const rad = (d: number) => (d * Math.PI) / 180;
  const dLat = rad(q.lat - p.lat);
  const dLon = rad(q.lon - p.lon);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(p.lat)) * Math.cos(rad(q.lat)) * Math.sin(dLon / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

/** `candidates` sorted nearest-first from `from` (ties by key for determinism). */
export function nearestRegions(from: string, candidates: string[]): string[] {
  return [...candidates].sort((x, y) => regionDistanceKm(from, x) - regionDistanceKm(from, y) || x.localeCompare(y));
}

export type LatencyCategory = "lowest" | "good" | "moderate" | "high";

/**
 * Honest, coarse latency CATEGORY of `region` for a visitor whose geographic
 * home region is `home` — derived from great-circle distance, never a made-up
 * millisecond figure. Same region = lowest; <3,000 km good; <9,000 km moderate;
 * further = high (a Malaysian customer on the Canada node is "high").
 */
export function latencyCategory(home: string, region: string): LatencyCategory {
  if (home === region) return "lowest";
  const d = regionDistanceKm(home, region);
  if (d < 3000) return "good";
  if (d < 9000) return "moderate";
  return "high";
}

export const LATENCY_LABEL: Record<LatencyCategory, string> = {
  lowest: "Lowest latency",
  good: "Good latency",
  moderate: "Moderate latency",
  high: "High latency",
};

export const AVAILABILITY_LABEL: Record<RegionAvailability, string> = {
  available: "Available",
  limited: "Limited availability",
  sold_out: "Sold out",
};

export type RegionStatusMap = Record<string, RegionAvailability>;

export type RegionDecision =
  | { ok: true; region: string; source: RegionSource }
  | { ok: false; region: string; source: RegionSource; message: string; alternatives: string[] };

/**
 * The single decision "which region does this order go in, and is it allowed".
 * Pure: availability is passed in (computed from the real scheduler by
 * lib/region-placement.ts), so this is trivially testable with fake data.
 *
 * - `explicitRegion` set -> that region is used as-is (source "explicit"). If it
 *   is sold out the decision is a refusal listing nearest alternatives.
 * - otherwise resolve from `country` ("geo") or fall back to DEFAULT_REGION
 *   ("default"); same refusal rule. NEVER substitutes another region.
 * - `availability[region]` missing (no node there at all) counts as sold out.
 */
export function decideRegion(args: {
  explicitRegion?: string | null;
  country?: string | null;
  availability: RegionStatusMap;
}): RegionDecision {
  const explicit = (args.explicitRegion ?? "").trim();
  let region: string;
  let source: RegionSource;
  if (explicit) {
    region = explicit;
    source = "explicit";
  } else {
    const g = regionForCountry(args.country);
    region = g.region;
    source = g.known ? "geo" : "default";
  }
  const status = args.availability[region];
  if (status && status !== "sold_out") return { ok: true, region, source };

  const open = Object.entries(args.availability)
    .filter(([k, v]) => k !== region && v !== "sold_out")
    .map(([k]) => k);
  const alternatives = nearestRegions(region, open);
  const name = customerRegionLabel(region);
  const alt = alternatives.slice(0, 2).map((k) => customerRegionLabel(k));
  const message =
    alt.length > 0
      ? `${name} is full right now, so we haven't placed or charged this order. ${alt.length > 1 ? `Nearest locations with room: ${alt.join(" or ")}.` : `Nearest location with room: ${alt[0]}.`} Pick one on the Location step if you want it there — your server will not be moved without you choosing it.`
      : `${name} is full right now, and no other location has room either, so we haven't placed or charged this order. Please try again shortly or contact support.`;
  return { ok: false, region, source, message, alternatives };
}

/**
 * Which region to PRESELECT in the wizard: the visitor's geographic region if it
 * can take orders, else the nearest region that can (the picker still shows the
 * truth about every region, and tells the customer why the default moved).
 * Falls back to the geographic region when nothing is open (it will show sold out).
 */
export function preselectRegion(args: {
  country?: string | null;
  availability: RegionStatusMap;
  regionKeys: string[];
}): { region: string | null; geoRegion: string; movedBecauseFull: boolean } {
  const geo = regionForCountry(args.country).region;
  if (args.regionKeys.length === 0) return { region: null, geoRegion: geo, movedBecauseFull: false };
  const open = args.regionKeys.filter((k) => (args.availability[k] ?? "sold_out") !== "sold_out");
  if (args.regionKeys.includes(geo) && open.includes(geo)) return { region: geo, geoRegion: geo, movedBecauseFull: false };
  if (open.length > 0) return { region: nearestRegions(geo, open)[0], geoRegion: geo, movedBecauseFull: true };
  return { region: args.regionKeys.includes(geo) ? geo : nearestRegions(geo, args.regionKeys)[0], geoRegion: geo, movedBecauseFull: false };
}

