import "server-only";
import { headers } from "next/headers";
import { db } from "./db";
import { scheduleNode, regionAvailability } from "./node-capacity";
import { countryFromHeaders } from "./geo-currency";
import { countryFromRequestIp } from "./geo-ip";
import { decideRegion, regionForCountry, type RegionSource, type RegionStatusMap } from "./region-pick";

/**
 * Server-side region resolution + placement for VPS and game orders
 * (2026-10-01 root-cause fix — see lib/region-pick.ts for the incident).
 *
 * Contract:
 *  - the region is ALWAYS decided here: explicit (what the customer picked) or
 *    resolved from their country ("geo") or the home default ("default");
 *  - the node is chosen only WITHIN that region (strict: a full region refuses);
 *  - a refusal never moves the order to another region — it tells the customer
 *    which regions are nearest and lets them choose.
 */

/** Best-known country for this customer: current request (CDN header, then IP) else their latest visit. */
export async function customerCountryHint(userId: string | null | undefined): Promise<string | null> {
  try {
    const h = await headers();
    const c = countryFromHeaders(h) || countryFromRequestIp(h);
    if (c) return c;
  } catch {
    // not in a request scope (webhook / worker) — fall through to stored visits
  }
  if (!userId) return null;
  try {
    const v = await db.visit.findFirst({
      where: { userId, country: { not: null } },
      orderBy: { createdAt: "desc" },
      select: { country: true },
    });
    return v?.country?.trim().toUpperCase() || null;
  } catch {
    return null;
  }
}

export type Placement =
  | { ok: true; node: { id: string; name: string; region: string }; region: string; source: RegionSource }
  | { ok: false; message: string; region: string; source: RegionSource; alternatives: string[] };

/**
 * Resolve region (explicit > geo > default) and pick a node inside it.
 * `country` (optional) overrides the lookup — used by tests/callers that
 * already know it.
 */
export async function placeInRegion(args: {
  ramMB: number;
  templateVmid?: number | null;
  region?: string | null;
  provider?: "OVH" | "HETZNER";
  userId?: string | null;
  country?: string | null;
}): Promise<Placement> {
  const explicit = (args.region ?? "").trim();
  const country = explicit ? null : args.country ?? (await customerCountryHint(args.userId));
  const target = explicit
    ? { region: explicit, source: "explicit" as RegionSource }
    : (() => {
        const g = regionForCountry(country);
        return { region: g.region, source: (g.known ? "geo" : "default") as RegionSource };
      })();

  const node = await scheduleNode(args.ramMB, {
    region: target.region,
    provider: args.provider,
    templateVmid: args.templateVmid,
    strict: true,
  });
  if (node) return { ok: true, node: { id: node.id, name: node.name, region: node.region }, region: target.region, source: target.source };

  // Refusal: work out the alternatives from the same scheduler, never auto-pick one.
  let availability: RegionStatusMap = {};
  try {
    availability = await regionAvailability(args.ramMB, { templateVmid: args.templateVmid });
  } catch {
    availability = {};
  }
  availability[target.region] = "sold_out";
  const d = decideRegion({ explicitRegion: target.region, availability });
  if (d.ok) {
    // unreachable (target forced sold_out) — keep the type checker honest
    return { ok: false, message: "That location is at capacity right now — please pick another.", region: target.region, source: target.source, alternatives: [] };
  }
  return { ok: false, message: d.message, region: target.region, source: target.source, alternatives: d.alternatives };
}

/** Record a refused-for-capacity order so the owner can see lost demand (AuditLog; no money moved). */
export async function logRegionRefusal(
  userId: string | null,
  product: "game" | "vps",
  p: Extract<Placement, { ok: false }>,
): Promise<void> {
  try {
    await db.auditLog.create({
      data: {
        userId,
        action: "order.region_full",
        detail: `product=${product} region=${p.region} regionSource=${p.source} nearest=${p.alternatives.join(",") || "none"}`,
      },
    });
  } catch {
    /* bookkeeping must never mask the refusal */
  }
}

