import { test } from "node:test";
import assert from "node:assert/strict";
import { ramProjectionExceedsCeiling } from "../lib/capacity.ts";

/**
 * `ramProjectionExceedsCeiling` is the pure boundary math `capacityCheckRamMB`
 * runs for EVERY order — premade plan or custom spec alike (lib/custom-plan.ts
 * customPlanCapacityCheck calls the exact same function). A custom spec can
 * request more RAM than any catalog plan, so this guard is what stands between a
 * huge custom order and silently overcommitting a node — these tests hold the
 * boundary exactly, since capacityCheckRamMB itself needs a live DB (committed
 * RAM across all servers) and is exercised at the integration level instead.
 */

test("requesting exactly the remaining headroom is allowed (boundary is inclusive)", () => {
  assert.equal(ramProjectionExceedsCeiling(/* committed */ 8000, /* ceiling */ 10000, /* add */ 2000), false);
});

test("requesting one more MB than the remaining headroom is rejected", () => {
  assert.equal(ramProjectionExceedsCeiling(8000, 10000, 2001), true);
});

test("a custom spec's oversized RAM request against an already-loaded host is rejected", () => {
  // A node already 90% committed (mirrors node_critical_pct's default) can't
  // additionally take a custom spec asking for more RAM than is left.
  const committed = 9000;
  const ceiling = 10000;
  const customRamMB = 8 * 1024; // an 8 GB custom RAM request, more than the 1000 MB left
  assert.equal(ramProjectionExceedsCeiling(committed, ceiling, customRamMB), true);
});

test("a modest custom spec against a nearly-empty host is allowed", () => {
  assert.equal(ramProjectionExceedsCeiling(0, 100000, 32 * 1024), false);
});
/**
 * Sandbox mode — the staging environment runs as a complete sandbox: the full
 * app works end to end (ordering, billing with play-money wallet debits, email
 * setup, server lifecycle), but NOTHING touches the outside world:
 *   - no real VMs are cloned/started on Proxmox (jobs are simulated)
 *   - no failover IPs are ordered from OVH (synthetic IPs are handed out)
 *   - no real money moves through Stripe (test keys + an instant-credit bypass)
 *
 * Gated entirely by the NXEON_SANDBOX env var, which is set ONLY in the staging
 * .env. In production the var is unset, so every check below is false and the
 * real integrations run exactly as before. This module is a plain (non-"use
 * server") module so both the app and the worker daemon can import it.
 */
export const SANDBOX = process.env.NXEON_SANDBOX === "1";

/**
 * A deterministic, non-routable synthetic public IPv4 for a sandbox server,
 * drawn from TEST-NET-2 (198.51.100.0/24, RFC 5737 — reserved for docs/examples,
 * never routed). Keeps the UI realistic without allocating anything real.
 */
