import { test } from "node:test";
import assert from "node:assert/strict";
import {
  regionForCountry,
  decideRegion,
  preselectRegion,
  nearestRegions,
  latencyCategory,
  DEFAULT_REGION,
  type RegionStatusMap,
} from "../lib/region-pick.ts";
import { defaultRegionChoice, type Region } from "../lib/nx/catalog.ts";

/**
 * 2026-10-01 incident: card-paid game orders carried NO region, the scheduler
 * picked across ALL regions, and Malaysian/German customers landed in Canada
 * (bhs1) while Singapore was full. These hold the rules that stop it:
 * geography -> region, explicit region respected, a full region REFUSES and
 * names alternatives instead of overflowing, unknown geo -> sgp1.
 */

test("geo -> region mapping covers the documented groups", () => {
  for (const cc of ["MY", "SG", "TH", "VN", "ID", "PH", "AU", "NZ", "IN", "JP", "KR"]) {
    assert.equal(regionForCountry(cc).region, "sgp1", cc);
  }
  for (const cc of ["DE", "FR", "GB", "PL", "SE", "AE", "SA", "EG", "ZA", "NG", "KE", "TR"]) {
    assert.equal(regionForCountry(cc).region, "fsn1", cc);
  }
  for (const cc of ["US", "CA", "MX", "BR", "AR", "CL", "CO"]) {
    assert.equal(regionForCountry(cc).region, "bhs1", cc);
  }
});

test("mapping is case/space tolerant; unknown or empty country -> sgp1 and known=false", () => {
  assert.deepEqual(regionForCountry(" de "), { region: "fsn1", known: true });
  for (const v of [null, undefined, "", "XX", "ZZZ", "T1"]) {
    assert.deepEqual(regionForCountry(v), { region: DEFAULT_REGION, known: false }, String(v));
  }
});

const open: RegionStatusMap = { sgp1: "available", fsn1: "available", bhs1: "available" };

test("explicit region is respected even when geo says otherwise", () => {
  const d = decideRegion({ explicitRegion: "fsn1", country: "MY", availability: open });
  assert.deepEqual(d, { ok: true, region: "fsn1", source: "explicit" });
});

test("no region + known country resolves from geo (source=geo)", () => {
  const d = decideRegion({ country: "DE", availability: open });
  assert.deepEqual(d, { ok: true, region: "fsn1", source: "geo" });
});

test("no region + unknown country -> sgp1 default (source=default)", () => {
  const d = decideRegion({ country: null, availability: open });
  assert.deepEqual(d, { ok: true, region: "sgp1", source: "default" });
});

test("REGRESSION: Malaysian customer, Singapore full -> refuse, never silently Canada", () => {
  const av: RegionStatusMap = { sgp1: "sold_out", fsn1: "available", bhs1: "available" };
  const d = decideRegion({ country: "MY", availability: av });
  assert.equal(d.ok, false);
  if (d.ok) return;
  assert.equal(d.region, "sgp1");
  // Nearest-first: Germany (~10,000 km) is nearer Singapore than Canada (~15,000 km).
  assert.deepEqual(d.alternatives, ["fsn1", "bhs1"]);
  assert.match(d.message, /Singapore is full/);
  assert.match(d.message, /haven't placed or charged/);
  assert.match(d.message, /Germany or Canada/);
});

test("explicit full region also refuses (the customer's pick is never overridden)", () => {
  const av: RegionStatusMap = { sgp1: "sold_out", fsn1: "available", bhs1: "available" };
  const d = decideRegion({ explicitRegion: "sgp1", country: "US", availability: av });
  assert.equal(d.ok, false);
  if (!d.ok) assert.equal(d.source, "explicit");
});

test("a region with no node at all counts as sold out; everything full -> no alternatives message", () => {
  const d = decideRegion({ explicitRegion: "hel1", availability: { sgp1: "sold_out" } });
  assert.equal(d.ok, false);
  if (!d.ok) {
    assert.deepEqual(d.alternatives, []);
    assert.match(d.message, /no other location has room/);
  }
});

test("limited still orders", () => {
  assert.equal(decideRegion({ explicitRegion: "sgp1", availability: { sgp1: "limited" } }).ok, true);
});

test("nearestRegions orders by distance and is deterministic", () => {
  assert.deepEqual(nearestRegions("bhs1", ["sgp1", "fsn1", "ash1"]), ["ash1", "fsn1", "sgp1"]);
  assert.deepEqual(nearestRegions("sgp1", ["fsn1", "bhs1"]), ["fsn1", "bhs1"]);
});

test("latency category is honest: same region lowest, Malaysia->Canada high", () => {
  assert.equal(latencyCategory("sgp1", "sgp1"), "lowest");
  assert.equal(latencyCategory("sgp1", "bhs1"), "high");
  assert.equal(latencyCategory("fsn1", "gra1"), "good");
  assert.equal(latencyCategory("sgp1", "fsn1"), "moderate");
});

test("wizard preselect: geo region when open, nearest open when full, sgp1 when unknown", () => {
  const keys = ["sgp1", "fsn1", "bhs1"];
  assert.deepEqual(preselectRegion({ country: "DE", availability: open, regionKeys: keys }), { region: "fsn1", geoRegion: "fsn1", movedBecauseFull: false });
  assert.equal(preselectRegion({ country: "US", availability: open, regionKeys: keys }).region, "bhs1");
  assert.equal(preselectRegion({ country: null, availability: open, regionKeys: keys }).region, "sgp1");
  const full = preselectRegion({ country: "MY", availability: { ...open, sgp1: "sold_out" }, regionKeys: keys });
  assert.deepEqual(full, { region: "fsn1", geoRegion: "sgp1", movedBecauseFull: true });
  // nothing open anywhere: keep the geo region (it shows sold out)
  const none = preselectRegion({ country: "MY", availability: { sgp1: "sold_out", fsn1: "sold_out", bhs1: "sold_out" }, regionKeys: keys });
  assert.equal(none.region, "sgp1");
});

const mk = (key: string, availability: Region["availability"]): Region => ({
  key, name: key, area: "x", flag: "sg", lat: 0, lon: 0, nodeIds: [], ms: 0, availability,
});

test("catalog defaultRegionChoice carries source + an honest note when the default moved", () => {
  const regions = [mk("bhs1", "available"), mk("fsn1", "available"), mk("sgp1", "sold_out")];
  const c = defaultRegionChoice(regions, "MY");
  assert.equal(c.region, "fsn1");
  assert.equal(c.source, "geo");
  assert.match(c.note ?? "", /Singapore is full right now/);
  assert.equal(defaultRegionChoice(regions, null).source, "default");
  assert.equal(defaultRegionChoice([mk("sgp1", "available")], "DE").region, "sgp1");
  assert.equal(defaultRegionChoice([], "DE").region, null);
});
